// Multiple classes in one file for the runnable demo.
package com.bank.guarantee;

import java.util.logging.*;

public class CopyDemo {
    private static final Logger log = Logger.getLogger(CopyDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Build chain G1 -> G2 -> G3
        GuaranteeNode g1 = new GuaranteeNode("G1");
        GuaranteeNode g2 = new GuaranteeNode("G2");
        GuaranteeNode g3 = new GuaranteeNode("G3");
        g1.next = g2; g2.next = g3;
        // Guarantor cross-references: G1->G3, G2->G1, G3->null
        g1.guarantor = g3;
        g2.guarantor = g1;
        g3.guarantor = null;

        log.info("Deep-copying the loan guarantee chain for regulatory archive");
        ChainCopier copier = new ChainCopier();
        GuaranteeNode copy = copier.deepCopy(g1);

        for (GuaranteeNode n = copy; n != null; n = n.next) {
            final GuaranteeNode cur = n;
            String g = (cur.guarantor != null) ? cur.guarantor.recordId : "none";
            log.info(() -> "Copy record " + cur.recordId + " guarantor=" + g
                + " isSameObjectAsOriginal=" + (cur == g1 || cur == g2 || cur == g3));
        }
        log.info("Independent deep copy created (no pointer references originals)");
    }
}

// ─── Would be in model/GuaranteeNode.java ───
class GuaranteeNode {
    String recordId;
    GuaranteeNode next;
    GuaranteeNode guarantor;  // the "random" pointer

    GuaranteeNode(String recordId) {
        this.recordId = recordId;
    }
}

// ─── Would be in service/ChainCopier.java ───
class ChainCopier {
    // Deep copy using a HashMap from original node to clone. O(n) time, O(n) space.
    GuaranteeNode deepCopy(GuaranteeNode head) {
        if (head == null) return null;

        java.util.Map<GuaranteeNode, GuaranteeNode> map = new java.util.HashMap<>();

        // Pass 1: clone every node, keyed by original
        for (GuaranteeNode cur = head; cur != null; cur = cur.next) {
            map.put(cur, new GuaranteeNode(cur.recordId));
        }

        // Pass 2: wire next and guarantor pointers using the map
        for (GuaranteeNode cur = head; cur != null; cur = cur.next) {
            GuaranteeNode clone = map.get(cur);
            clone.next = map.get(cur.next);          // map.get(null) returns null
            clone.guarantor = map.get(cur.guarantor);
        }
        return map.get(head);
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override
    public String format(java.util.logging.LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(record.getMillis()),
            record.getLevel().getName(),
            record.getMessage());
    }
}
